-- Community reports (210 FICTIONAL reports in Ghana, EPSG:4326) for the video
-- 'Community Reports from G3W to GeoSight'. Recreates public.community_reports.
-- Run after ghana_regions.sql. Then run report_stats.sql to create the per-region view.

CREATE EXTENSION IF NOT EXISTS postgis;
DROP VIEW IF EXISTS public.report_stats;
DROP TABLE IF EXISTS public.community_reports;
CREATE TABLE public.community_reports (
  id serial PRIMARY KEY,
  report_date date NOT NULL DEFAULT current_date,
  category text,
  description text,
  status text DEFAULT 'New',
  reporter_type text,
  water_point_code text,
  geom geometry(Point,4326));
SELECT setval('public.community_reports_id_seq', (SELECT max(id) FROM public.community_reports));
CREATE INDEX community_reports_geom_gix ON public.community_reports USING gist (geom);
ANALYZE public.community_reports;
